-- Lead Desk · Lead generators (9 Nov 2026)
-- Run once in Supabase → SQL Editor, after 21_pricing.sql. Safe to run again. No leads are changed.
--
-- Adds the list of lead generators to the settings (Products & settings → Lead generators), starting with the
-- two Marketing team members. Their leads are found by "Generated by" (name or other spellings), so past leads
-- count from the start without editing them. Only added if the list doesn't exist yet: later edits stand.
-- Everyone signed in can already read the settings; only a Supervisor (settings.manage) can change them.

update public.docs
set doc = jsonb_set(doc, '{generators}', '[
  {"name":"Pratibha","dept":"Marketing","aliases":[],"email":""},
  {"name":"Nazreen","dept":"Marketing","aliases":["Nasreen"],"email":""}
]'::jsonb)
where path = 'config/settings' and not (doc ? 'generators');

-- make sure "Marketing" is one of the departments on the lead form
update public.docs
set doc = jsonb_set(doc, '{departments}', coalesce(doc->'departments','[]'::jsonb) || '["Marketing"]'::jsonb)
where path = 'config/settings' and not (coalesce(doc->'departments','[]'::jsonb) ? 'Marketing');

-- Check
select doc->'generators' as lead_generators from public.docs where path = 'config/settings';
